{
  "config": {
    "schemaVersion": 1,
    "game_id": "{{gameId}}",
    "theme": {
      "mode": "dark",
      "fonts": {
        "heading": {
          "family": "Unbounded",
          "source": "google"
        },
        "body": {
          "family": "Inter",
          "source": "google"
        }
      },
      "frame": {
        "style": "solid",
        "width": 1,
        "color": "#2C3B3E",
        "corners": "soft"
      },
      "buttons": {
        "style": "filled",
        "case": "normal"
      },
      "panel": {
        "opacity": 1,
        "blur": false
      },
      "colors": {
        "brand": "#80EAFF",
        "background": "#141D1F",
        "surface": "#1B2628",
        "text": "#E8ECED",
        "muted": "#B7C5C8"
      },
      "textures": {
        "panel": {
          "asset": "tex_grid",
          "fit": "tile",
          "strength": "subtle"
        }
      }
    },
    "layout": {
      "position": "bottom-right",
      "startCollapsed": true
    },
    "friends": {
      "enabled": true
    },
    "clan": {
      "enabled": true,
      "maxMembers": 30,
      "tags": true,
      "descriptionMax": 140,
      "badges": {
        "source": "developer",
        "allowed": [
          "star",
          "diamond",
          "peak",
          "spark",
          "moon",
          "cross"
        ]
      },
      "screens": {
        "discover": {
          "enabled": true
        },
        "create": {
          "enabled": true
        },
        "home": {
          "enabled": true,
          "header": "compact",
          "showStats": true
        },
        "members": {
          "enabled": true
        }
      }
    },
    "chat": {
      "enabled": true,
      "layout": "bubbles",
      "directMessages": true,
      "clanChat": true,
      "maxMessageLength": 20,
      "slowModeSeconds": 0,
      "profanityFilter": true,
      "historyLimit": 50
    },
    "texts": {
      "terms": {
        "clan": "Clan",
        "clans": "Clans"
      },
      "labels": {
        "panelTitle": "Arena Social",
        "createCta": "+ Start a {clan}"
      }
    }
  }
}

